useEffect(() => {
  const userId = user?.userId || user?.user_id || user?.sub || user?.id;
  const allowedStaffRoles = ["admin", "staff", "teacher", "editor", "contributor"];
  if (!userId || !user || !user.role || !allowedStaffRoles.includes(user.role)) return;

  // Data-reload mapping: featureKey → loader function
  const getFeatureReloaders = (): Record<string, () => void> => ({
    student_management: loadStudents,
    staff_management: loadStaff,
    batch_management: loadBatches,
    fees_management: loadStudents,
    marks_management: loadStudents,
    lms_daily_content: loadLmsDailyContent,
    lms_quiz_posting: loadTodayQuiz,
    lms_live_classes: loadLiveSessions,
    lms_recorded_videos: loadRecordedClasses,
    lms_resources: loadLmsResources,
    lms_courses: loadLmsCourses,
    admissions: loadAdmissions,
    leads: loadLeads,
    campaigns: loadCampaigns,
    alumni_feedback: loadFeedback,
    test_creation: loadTests,
    question_bank: loadQuestions,
    examinations: loadTests,
    test_results: loadTests,
  });

  let unsub: (() => void) | undefined;
  try {
    // Listen to notifications that belong strictly to this user
    const qUserNotifs = query(collection(db, "notifications"), where("requestedByUserId", "==", userId));
    unsub = onSnapshot(qUserNotifs, (snapshot) => {
      snapshot.docChanges().forEach((change) => {
        if (change.type !== "modified") return;
        const data = change.doc.data();
        // Only react to our own submissions that have just been resolved
        if (data.requestedByUserId !== userId) return;
        if (data.status !== "approved" && data.status !== "rejected") return;

        // If approved → reload relevant collection so data appears immediately
        if (data.status === "approved") {
          const reloaders = getFeatureReloaders();
          reloaders[data.feature]?.();
        }

        // Remove from pendingSubmissions regardless of outcome
        setPendingSubmissions(prev => prev.filter(k => k !== data.feature));
        // Refresh the pending approvals banner
        loadPendingApprovals();
      });
    });
  } catch (e) {
    console.log("[ApprovalSync] Failed to attach real-time listener:", e);
  }

  return () => { if (unsub) unsub(); };
}, [user?.userId]);

useEffect(() => {
  if (!waitingRoomTest) return;
  const tick = () => {
    const startMs = parseTestTimeMs(waitingRoomTest.startTime);
    const remaining = Math.max(0, Math.floor((startMs - Date.now()) / 1000));
    setWaitingRoomTimeLeft(remaining);
    if (remaining <= 0) {
      // Test has started — close waiting room and auto-launch exam directly
      const targetTest = waitingRoomTest;
      setWaitingRoomTest(null);
      setNowTick(Date.now()); // force live-test list refresh
      if (targetTest) {
        setTimeout(() => {
          startExam(targetTest);
        }, 300);
      }
    }
  };
  tick();
  const timer = setInterval(tick, 1000);
  return () => clearInterval(timer);
}, [waitingRoomTest]);

useEffect(() => {
  if (!activeAttempt) return;
  const attemptId = activeAttempt.attemptId;

  // Tracks a JSON snapshot of the last successfully synced answers.
  // Scoped to this useEffect instance so it resets fresh for every new attempt.
  let lastSyncedHash = "";

  const syncAnswers = async () => {
    try {
      const draft = examLocalStorage.getDraft(attemptId);
      if (!draft || !draft.answers) return;

      // Build a stable hash of the current answer map to detect changes.
      // JSON.stringify on a plain object is deterministic enough here since
      // keys are question IDs (UUIDs) and values are single-letter answer strings.
      const currentHash = JSON.stringify(draft.answers);

      // Skip the API call entirely if nothing changed since the last sync.
      // This saves Firestore writes during review phases or when the student
      // is reading a question without having changed any answer yet.
      if (currentHash === lastSyncedHash) return;

      const formattedBatch = Object.entries(draft.answers).map(([qId, val]) => ({
        questionId: qId,
        answer: val
      }));

      if (formattedBatch.length > 0) {
        // Include x-attempt-id header as bypass so this still works if JWT session expired.
        await api.post(
          `/test-portal/examination/autosave/${attemptId}`,
          { answers: formattedBatch },
          { headers: { "user-id": user?.userId || "", "x-attempt-id": attemptId } }
        );
        // Only update the hash after a successful API call.
        // If the request fails (network drop), lastSyncedHash stays stale so the
        // next interval will retry — ensuring no answers are silently lost.
        lastSyncedHash = currentHash;
        console.log("Automatically synchronized answers to cloud:", formattedBatch.length);
      }
    } catch (e) {
      // Do NOT update lastSyncedHash on failure — next interval will retry.
      console.log("Background exam sync warning:", e);
    }
  };

  const intervalId = setInterval(syncAnswers, 60000);
  return () => {
    clearInterval(intervalId);
    // Run a final sync on cleanup/exit regardless of dirty flag —
    // ensures the very last answers are flushed before the component unmounts.
    syncAnswers().catch(() => { });
  };
}, [activeAttempt]);

useEffect(() => {
  if (!activeAttempt || Platform.OS !== "web" || typeof window === "undefined") return;

  const handleOffline = () => {
    showToast(
      "📶 Network disconnected. You can continue answering all questions — your answers are saved locally and will sync automatically once reconnected.",
      "warning"
    );
  };

  // ── Token auto-refresh every 10 minutes during active exam ────────────────
  // This is the primary fix for "answers show as Unattempted" —
  // without refresh, the JWT session expires and all API calls return 401,
  // silently dropping every answer save.
  const refreshExamToken = async () => {
    try {
      if (typeof localStorage === "undefined") return;
      const stored = JSON.parse(localStorage.getItem("nermai_auth_user") || "{}");
      if (!stored.refreshToken || !stored.sessionId) return;
      const baseUrl = getBaseUrl();
      const res = await fetch(`${baseUrl}/api/auth/refresh`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ refreshToken: stored.refreshToken, sessionId: stored.sessionId })
      });
      const data = await res.json();
      if (data?.data?.token) {
        stored.token = data.data.token;
        if (data.data.refreshToken) stored.refreshToken = data.data.refreshToken;
        if (data.data.sessionId) stored.sessionId = data.data.sessionId;
        localStorage.setItem("nermai_auth_user", JSON.stringify(stored));
        console.log("[ExamTokenRefresh] Token refreshed successfully during exam.");
      }
    } catch (e) {
      console.log("[ExamTokenRefresh] Refresh failed (non-critical, bypass will handle):", e);
    }
  };

  // Refresh immediately on exam start, then every 10 minutes
  refreshExamToken();
  const tokenRefreshInterval = setInterval(refreshExamToken, 10 * 60 * 1000);

  const handleOnline = async () => {
    showToast(
      "✅ Network reconnected! Syncing offline answers to server...",
      "success"
    );
    syncAnswers().catch(() => {});
  };

  window.addEventListener("offline", handleOffline);
  window.addEventListener("online", handleOnline);

  return () => {
    clearInterval(tokenRefreshInterval);
    window.removeEventListener("offline", handleOffline);
    window.removeEventListener("online", handleOnline);
  };
}, [activeAttempt, user]);

